<?php require_once __DIR__.'/includes/bootstrap.php';require_customer();$page_title='My Account';$s=$pdo->prepare('SELECT * FROM orders WHERE customer_id=? ORDER BY created_at DESC');$s->execute([customer()['id']]);$orders=$s->fetchAll();require __DIR__.'/includes/header.php';?>
<h1>স্বাগতম, <?=e(customer()['name'])?></h1><div class="card"><h2>আমার অর্ডার</h2><div class="table-wrap"><table><tr><th>অর্ডার</th><th>তারিখ</th><th>স্ট্যাটাস</th><th>মোট</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['created_at'])?></td><td><?=e($o['status'])?></td><td><?=money($o['total'])?></td></tr><?php endforeach;?></table></div><?php if(!$orders):?><p>এখনো কোনো অর্ডার নেই।</p><?php endif;?></div><?php require __DIR__.'/includes/footer.php';?>
